PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?person ?birthDate WHERE {
  VALUES ?person { dbr:Madeleine_Robinson dbr:Dušan_Poliačik }
  OPTIONAL { ?person dbp:birthDate ?dbpDate . }
  OPTIONAL { ?person dbo:birthDate ?dboDate . }
  BIND (COALESCE(?dbpDate, ?dboDate) AS ?birthDate)
}
LIMIT 100

